,asideNote=S[52],talentString="05322522312231153105000000000000000003",ranks={{tree="Arcane",name=S[378],r=5,max=5},{tree="Arcane",name=S[583],r=3,max=3},{tree="Arcane",name=S[380],r=2,max=2},{tree="Arcane",name=S[592],r=2,max=2},{tree="Arcane",name=S[367],r=5,max=5},{tree="Arcane",name=S[381],r=2,max=2},{tree="Arcane",name=S[602],r=2,max=2},{tree="Arcane",name=S[618],r=3,max=3},{tree="Arcane",name=S[440],r=1,max=1},{tree="Arcane",name=S[593],r=2,max=2},{tree="Arcane",name=S[521],r=2,max=2},{tree="Arcane",name=S[410],r=3,max=3},{tree="Arcane",name=S[557],r=1,max=1},{tree="Arcane",name=S[500],r=1,max=1},{tree="Arcane",name="Arcane Mind",r=5,max=5},{tree="Arcane",name=S[558],r=3,max=3},{tree="Arcane",name=S[559],r=1,max=1},{tree="Fire",name="Accelerant",r=5,max=5},{tree="Frost",name="Precision",r=3,max=3}},order={{l1=10,l2=14,tree="Arcane",name=S[378],r1=1,r2=5,max=5},{l1=15,l2=19,tree="Arcane",name=S[367],r1=1,r2=5,max=5},{l1=20,l2=20,tree="Arcane",name=S[440],r1=1,r2=1,max=1},{l1=21,l2=23,tree="Arcane",name=S[618],r1=1,r2=3,max=3},{l1=24,l2=24,tree="Arcane",name=S[381],r1=1,r2=1,max=2},{l1=25,l2=25,tree="Arcane",name=S[557],r1=1,r2=1,max=1},{l1=26,l2=26,tree="Arcane",name=S[381],r1=2,r2=2,max=2},{l1=27,l2=29,tree="Arcane",name=S[410],r1=1,r2=3,max=3},{l1=30,l2=30,tree="Arcane",name=S[500],r1=1,r2=1,max=1},{l1=31,l2=35,tree="Arcane",name="Arcane Mind",r1=1,r2=5,max=5},{l1=36,l2=38,tree="Arcane",name=S[558],r1=1,r2=3,max=3},{l1=39,l2=39,tree="Arcane",name=S[380],r1=1,r2=1,max=2},{l1=40,l2=40,tree="Arcane",name=S[559],r1=1,r2=1,max=1},{l1=41,l2=41,tree="Arcane",name=S[380],r1=2,r2=2,max=2},{l1=42,l2=43,tree="Arcane",name=S[602],r1=1,r2=2,max=2},{l1=44,l2=46,tree="Frost",name="Precision",r1=1,r2=3,max=3},{l1=47,l2=51,tree="Fire",name="Accelerant",r1=1,r2=5,max=5},{l1=52,l2=54,tree="Arcane",name=S[583],r1=1,r2=3,max=3},{l1=55,l2=56,tree="Arcane",name=S[592],r1=1,r2=2,max=2},{l1=57,l2=58,tree="Arcane",name=S[593],r1=1,r2=2,max=2},{l1=59,l2=60,tree="Arcane",name=S[521],r1=1,r2=2,max=2}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[390]},{t="h1",x="Arcane",sub=S[501]},{t="p",s="lede",x="Single-target PvE Arcane: stack Arcane Blast, spend Accelerant-shortened Arcane Wrath and Missile Barrage procs, and open Arcane Power for boss burst, with a small Fire and Frost support package. Not built for PvP or AoE farming."},{t="pills",list={S[411],S[262],S[429]}},{t="anchor",id="journey"},{t="kicker",x=S[539]},{t="h2",x=S[314]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Take channel protection and Clearcasting"},{t="p",x="Improved Channeling reaches 5/5 by level 14 and Arcane Concentration by 19. Clearcasting turns some casts free, and Improved Channeling stops hits from costing you cast time while you channel or cast. Fight one enemy at a time and Polymorph extras instead of pulling groups."},{t="p",s="level",x="20–39 · Build the Arcane engine"},{t="p",x="Arcane Blast arrives at 20 and Arcane Wrath at 25. Missile Barrage is 2/2 by 26, Arcane Meditation 3/3 by 29, Presence of Mind at 30, Arcane Mind 5/5 by 35 and Arcane Instability 3/3 by 38. Use short Blast sequences and extend them only when your mana and the target's health justify the cost."},{t="p",s="level",x="40–60 · Add Fire and Frost support"},{t="p",x="Arcane Power arrives at 40, then the last Arcane Subtlety point (41) and Arcane Geometry (42–43). Precision (44–46) adds spell hit to every school and Accelerant (47–51) shortens Arcane Wrath; the last nine points finish the Arcane tree with Arcane Resilience, Magic Absorption, Arcane Shielding and Improved Counterspell for armor and protection. Rely on baseline Frost Nova, Blink and Polymorph for control."},{t="anchor",id="talents"},{t="kicker",x=S[363]},{t="h2",x=S[411]},{t="p",x=S[38]},{t="widget",w="talents"},{t="h4",s="summary",x=S[401]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[343]},{t="p",x=S[67]},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; expect poor results in either, because Arcane Blast's rising mana cost and the 6-second Arcane Wrath cooldown reward a long fight against one target rather than quick bursts or many weak enemies."},{t="p",s="notice",x="This is a single-target PvE build, not a measured raid optimum. Forty-three Arcane points carry the damage and protection, five Fire points in Accelerant make Arcane Wrath faster, and three Frost points in Precision add spell hit. Nothing in this allocation improves area damage."},{t="anchor",id="stats"},{t="kicker",x=S[453]},{t="h2",x=S[382]},{t="p",x="Arcane wants spell damage and a large mana pool. Arcane Blast and Arcane Wrath also scale with Intellect and maximum mana, so Intellect is worth more here than for the other Mage specs."},{t="h3",x=S[522]},{t="stat",i=1,b=S[560],x=S[502]},{t="stat",i=2,b="Intellect",x="bigger mana pool, more spell crit"},{t="stat",i=3,b="Stamina",x="safer pulls"},{t="stat",i=4,b="Spirit",x=S[344]},{t="p",s="small",x="Precision (3/3) gives 6% hit to all your spells, which covers most of the hit you need against enemies of your level, so hit on leveling gear is a bonus."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[502]},{t="stat",i=3,b=S[510],x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="stat",i=6,b="Spirit",x=""},{t="p",s="small",x="Precision adds 6% hit to all your spells. Spell penetration and haste are useful extras when an item offers them."},{t="p",s="notice",x=S[35]},{t="anchor",id="combat"},{t="kicker",x=S[383]},{t="h2",x=S[523]},{t="p",x=S[66]},{t="h4",x="Prepare for a full-length fight"},{t="p",x="Apply Arcane Intellect and choose an armor spell for the encounter. Start from range, know your escape route, and plan mana for the whole fight, not only the opening. This build is meant for one target at a time: pull one enemy or boss, kill it, then recover."},{t="h4",x="Build only the Arcane Blast stacks you can afford"},{t="p",x="Each Arcane Blast gives spell damage equal to 12% of your Intellect and raises its own mana cost by 100%, stacking up to 4 times and lasting 18 seconds from the first application. Establish a useful bonus, then cast efficient spells while it lasts. Arcane Impact adds 6% crit to your Arcane spells."},{t="h4",x="Weave Arcane Wrath and Missile Barrage"},{t="p",x="Cast Arcane Wrath whenever it is ready (3.5 second cast, 6 second cooldown, with Accelerant shaving 0.5 seconds off). Missile Barrage gives Arcane Blast a 40% chance, and Arcane Wrath, Fireball, Frostbolt and Frostfire Bolt a 20% chance, to make your next Arcane Missiles shorter, free and faster. Spend a Clearcasting proc on your most expensive stacked Blast rather than on a cheap spell; Arcane Missiles cast with Missile Barrage does not use up Clearcasting."},{t="h4",x="Use cooldowns when casting is safe"},{t="p",x="Arcane Power makes your spells deal 30% more damage and cost 30% more mana for 15 seconds, so pair it with a target that will live through the window and a full mana bar. Presence of Mind makes your next cast instant for a moving or finishing hit. Time Evocation for a protected channel rather than using it while being hit."},{t="h4",x="Keep control as a tool, not a rotation"},{t="p",x="Improved Frost Nova shortens Frost Nova's cooldown by 4 seconds for a safer escape, and Blink and Polymorph remain your baseline tools. Use them to reset a pull, not to rebuild an AoE routine. Let the group tank handle packs and do not move into area damage for a few extra casts."},{t="h4",x=S[325]},{t="p",x=S[23]},{t="abil",names={S[440],S[557],"Arcane Missiles",S[559],S[500],"Blink","Mana Gem"}},{t="h3",x=S[487]},{t="p",x="Intellect is especially relevant to the Arcane Blast bonus, Arcane Mind and the mana pool that supports Arcane Wrath. Compare it with spell damage, spell hit, critical chance, Spirit and enough Stamina to survive. Precision is 3/3 in this build, giving +6% spell hit to all schools; Arcane Subtlety also lowers your target's resistances. A high weapon DPS number does not increase spell damage."},{t="p",x=S[74]},{t="h3",x=S[374]},{t="p",x=S[24]},{t="p",x=S[42]},{t="p",x=S[57]},{t="anchor",id="macros"},{t="kicker",x=S[503]},{t="h2",x=S[280]},{t="p",x=S[45]},{t="p",s="notice",x=S[33]},{t="macro",n=S[447],x=S[146],code=S[155]},{t="macro",n=S[415],x=S[157],code=S[130]},{t="macro",n=S[402],x=S[131],code=S[111]},{t="macro",n=S[375],x=S[208],code=S[120]},{t="macro",n="Blink now",x=S[188],code=S[259]},{t="macro",n=S[524],x=S[218],code=S[213]},{t="macro",n=S[454],x=S[113],code=S[243]},{t="macro",n=S[430],x=S[179],code=S[219]},{t="macro",n=S[416],x=S[158],code=S[207]},{t="macro",n=S[561],x=S[202],code=S[326]},{t="macro",n=S[441],x=S[135],code=S[220]},{t="macro",n=S[455],x=S[180],code=S[251]},{t="p",s="small",x=S[108]},{t="anchor",id="dungeons"},{t="kicker",x=S[511]},{t="h2",x=S[345]},{t="p",x=S[39]},{t="widget",w="rarity"},{t="p",s="notice",x=S[28]},{t="p",s="notice",x=S[34]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[384]},{t="h2",x=S[341]},{t="p",x=S[41]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[403]},{t="h2",x=S[315]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[385]},{t="h2",x=S[292]},{t="p",x=S[30]},{t="widget",w="quest"},{t="anchor",id=S[360]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[54]}}},{id="fire",name="Fire",token="FIRE",gearBrackets={{b="Quest rewards",no="Quest rewards that fit this spec's stat priority, sorted by quest level. The tooltip names the quest, its level, the quest giver and the faction. Quest level is not the minimum pickup level.",keys={"st-mage-2","st-mage-3","mage-g130","mage-g70","mage-g56","mage-g3","mage-g37","mage-g22","mage-g23","mage-g64","mage-g135","mage-g127","mage-g26","ma