440],r=1,max=1},{tree="Arcane",name=S[410],r=1,max=3},{tree="Fire",name=S[442],r=5,max=5},{tree="Fire",name="Accelerant",r=5,max=5},{tree="Fire",name="Ignite",r=5,max=5},{tree="Fire",name="Pyroblast",r=1,max=1},{tree="Fire",name=S[379],r=2,max=2},{tree="Fire",name=S[603],r=3,max=3},{tree="Fire",name="Heating Up",r=1,max=1},{tree="Fire",name=S[391],r=3,max=3},{tree="Fire",name=S[619],r=3,max=3},{tree="Fire",name="Fire Power",r=3,max=3},{tree="Fire",name="Combustion",r=1,max=1},{tree="Frost",name="Precision",r=3,max=3}},order={{l1=10,l2=14,tree="Fire",name="Accelerant",r1=1,r2=5,max=5},{l1=15,l2=19,tree="Fire",name="Ignite",r1=1,r2=5,max=5},{l1=20,l2=20,tree="Fire",name="Pyroblast",r1=1,r2=1,max=1},{l1=21,l2=24,tree="Fire",name=S[442],r1=1,r2=4,max=5},{l1=25,l2=25,tree="Fire",name="Heating Up",r1=1,r2=1,max=1},{l1=26,l2=28,tree="Fire",name=S[603],r1=1,r2=3,max=3},{l1=29,l2=31,tree="Fire",name=S[391],r1=1,r2=3,max=3},{l1=32,l2=33,tree="Fire",name=S[379],r1=1,r2=2,max=2},{l1=34,l2=36,tree="Fire",name=S[619],r1=1,r2=3,max=3},{l1=37,l2=39,tree="Fire",name="Fire Power",r1=1,r2=3,max=3},{l1=40,l2=40,tree="Fire",name="Combustion",r1=1,r2=1,max=1},{l1=41,l2=43,tree="Frost",name="Precision",r1=1,r2=3,max=3},{l1=44,l2=44,tree="Fire",name=S[442],r1=5,r2=5,max=5},{l1=45,l2=49,tree="Arcane",name=S[378],r1=1,r2=5,max=5},{l1=50,l2=51,tree="Arcane",name=S[380],r1=1,r2=2,max=2},{l1=52,l2=56,tree="Arcane",name=S[367],r1=1,r2=5,max=5},{l1=57,l2=58,tree="Arcane",name=S[381],r1=1,r2=2,max=2},{l1=59,l2=59,tree="Arcane",name=S[440],r1=1,r2=1,max=1},{l1=60,l2=60,tree="Arcane",name=S[410],r1=1,r2=1,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[390]},{t="h1",x="Fire",sub=S[501]},{t="p",s="lede",x="Single-target PvE Fire: Fireball is your main cast, with Accelerant shortening it, Ignite, Improved Scorch and Heating Up turning it into boss damage, Combustion for burst, and Arcane support for Clearcasting, mana and Arcane Blast. Not built for PvP or AoE farming."},{t="pills",list={S[398],S[262],S[429]}},{t="anchor",id="journey"},{t="kicker",x=S[539]},{t="h2",x=S[314]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Cast faster and let Ignite burn"},{t="p",x="Accelerant reaches 5/5 by level 14 and shortens Fireball by 0.5 seconds, so Fireball is your main cast. Ignite is 5/5 by 19 and adds a burn after each Fire crit. Keep Frostbolt for control, kill one target at a time, and carry a wand for low-mana finishes."},{t="p",s="level",x="20–39 · Add Pyroblast and boss damage"},{t="p",x="Pyroblast arrives at 20 and Heating Up at 25. Improved Scorch is 3/3 by 28, Master of Elements 3/3 by 31, Improved Fire Blast 2/2 by 33, Critical Mass 3/3 by 36 and Fire Power 3/3 by 39. Read your Heating Up stacks before choosing the next cast."},{t="p",s="level",x="40–60 · Frostfire Bolt takes over"},{t="p",x="Combustion arrives at 40 for burst. Precision (41–43) adds spell hit to every school and Incineration reaches 5/5 at 44. The last sixteen points go into Arcane: Improved Channeling, Arcane Subtlety and Arcane Concentration for Clearcasting, then Missile Barrage, Arcane Blast and one point of Arcane Meditation for mana while casting. There is no Ice Barrier, Presence of Mind or Arcane Power here, so plan escapes around your baseline tools."},{t="anchor",id="talents"},{t="kicker",x=S[363]},{t="h2",x=S[398]},{t="p",x=S[38]},{t="widget",w="talents"},{t="h4",s="summary",x=S[401]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[343]},{t="p",x=S[67]},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; the Fire damage comes from long single-target casts and stacking effects, not from burst against several enemies or from controlling another player."},{t="p",s="notice",x="This is a deep Fire build: 32 Fire points with Combustion, 16 Arcane points for Clearcasting, mana regeneration and Arcane Blast, and 3 Frost points in Precision for hit. Fireball, Scorch, Fire Blast and Pyroblast carry the damage. Blast Wave, Improved Flamestrike and other area-damage talents are not taken."},{t="anchor",id="stats"},{t="kicker",x=S[453]},{t="h2",x=S[382]},{t="p",x="Fire wants spell damage and critical strike: crits build Heating Up, trigger Ignite and refund mana through Master of Elements."},{t="h3",x=S[522]},{t="stat",i=1,b=S[560],x=S[517]},{t="stat",i=2,b="Intellect",x=S[545]},{t="stat",i=3,b="Stamina",x="safer pulls"},{t="stat",i=4,b="Spirit",x=S[344]},{t="p",s="small",x="Precision gives 6% hit to all your spells, which covers enemies of your level."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[517]},{t="stat",i=3,b=S[510],x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="stat",i=6,b="Spirit",x=""},{t="p",s="small",x="With Precision you need about 11% hit from gear. Spell penetration and haste are useful extras."},{t="p",s="notice",x=S[35]},{t="anchor",id="combat"},{t="kicker",x=S[383]},{t="h2",x=S[523]},{t="p",x=S[66]},{t="h4",x="Open from range"},{t="p",x="Open with Fireball (Accelerant makes it 0.5 seconds faster at 5/5), or with Pyroblast on a target that will live long enough. Frostbolt is for establishing space when control matters more than damage. Pull one enemy at a time and finish it before looking at the next."},{t="h4",x="From 40, make Frostfire Bolt your main cast"},{t="p",x="Fireball is the spell you cast most: Accelerant shortens it by 0.5 seconds, its non-periodic crits build Heating Up, every Fire crit triggers Ignite, and Master of Elements refunds 30% of the base mana cost of Fire crits. Incineration 5/5 adds critical chance to your affected Fire spells. Arcane Concentration gives you free Clearcasting casts: spend them on Fireball or Pyroblast."},{t="h4",x="Apply Improved Scorch on durable targets"},{t="p",x="Improved Scorch is 3/3, so every Scorch applies Fire vulnerability: +3% Fire damage per stack, up to 5 stacks, lasting 30 seconds. On a boss or other long fight, build it first and keep it up; on a short quest fight it can cost more time than it saves. Fire Power rewards the Fire effects you keep on the target."},{t="h4",x="Read Heating Up before Pyroblast"},{t="p",x="Non-periodic crits from Fireball, Fire Blast and Scorch each cut the cast time of your next Pyroblast by 25%, up to 3 stacks, and Fire Blast adds an extra stack when it deals damage. Improved Fire Blast makes Fire Blast available 2 seconds sooner. Cast a shortened Pyroblast when you have a window and the target will live; three stacks reduce its cast time by 75%, not to an automatic instant cast."},{t="h4",x="Use Combustion at the start of a damage window"},{t="p",x="Activate Combustion when the target will survive your whole burst: each Fire damage hit raises your Fire crit chance by 10% until you land 3 non-periodic crits. Combine it with a Pyroblast and your Heating Up stacks, and keep Critical Mass and Fire Power in mind when you compare gear."},{t="h4",x="Treat the Frost package as support"},{t="p",x="Precision adds spell hit to every school. Improved Channeling and Arcane Concentration give you free Clearcasting casts, Missile Barrage can make Arcane Missiles free and faster, and Arcane Blast adds spell damage from your Intellect for a short burst; Arcane Meditation keeps some mana regeneration going while you cast."},{t="h4",x="Stay on single targets"},{t="p",x="This build has no Counterspell silence, Impact stun or area talents, and it is not meant for PvP or AoE farming. In groups, leave pack damage to others and keep Fireball and Pyroblast on your boss target."},{t="h4",x=S[325]},{t="p",x=S[23]},{t="abil",names={"Fireball","Frostbolt","Fire Blast","Pyroblast","Scorch","Combustion","Mana Gem"}},{t="h3",x=S[487]},{t="p",x="Compare Fire spell damage, Intellect, spell critical chance and hit. Precision is 3/3 here, giving +6% spell hit to every school, and Ignite, Master of Elements and Heating Up all reward crits. Spirit and Stamina can improve real questing uptime, and Intellect also feeds the Arcane Blast bonus."},{t="p",x=S[74]},{t="h3",x=S[374]},{t="p",x=S[24]},{t="p",x=S[42]},{t="p",x=S[57]},{t="anchor",id="macros"},{t="kicker",x=S[503]},{t="h2",x=S[280]},{t="p",x=S[45]},{t="p",s="notice",x=S[33]},{t="macro",n=S[447],x=S[146],code=S[155]},{t="macro",n=S[415],x=S[157],code=S[130]},{t="macro",n=S[402],x=S[131],code=S[111]},{t="macro",n=S[375],x=S[208],code=S[120]},{t="macro",n="Blink now",x=S[188],code=S[259]},{t="macro",n=S[524],x=S[218],code=S[213]},{t="macro",n=S[454],x=S[113],code=S[243]},{t="macro",n=S[430],x=S[179],code=S[219]},{t="macro",n=S[416],x=S[158],code=S[207]},{t="macro",n=S[561],x=S[202],code=S[326]},{t="macro",n=S[441],x=S[135],code=S[220]},{t="macro",n=S[455],x=S[180],code=S[251]},{t="p",s="small",x=S[108]},{t="anchor",id="dungeons"},{t="kicker",x=S[511]},{t="h2",x=S[345]},{t="p",x=S[39]},{t="widget",w="rarity"},{t="p",s="notice",x=S[28]},{t="p",s="notice",x=S[34]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[384]},{t="h2",x=S[341]},{t="p",x=S[41]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[403]},{t="h2",x=S[315]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[385]},{t="h2",x=S[292]},{t="p",x=S[30]},{t="widget",w="quest"},{t="anchor",id=S[360]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[54]}}},{id="frost",name="Frost",token="FROST",gearBrackets={{b="Quest rewards",no="Quest rewards that fit this spec's stat priority, sorted by quest level. The tooltip names the quest, its level, the quest giver and the faction. Quest level is not the minimum pickup level.",keys={"st-mage-1","st-mage-2","mage-g130","mage-g70","mage-g56","mage-g3","mage-g37","mage-g22","mage-g23","mage-g64","mage-g135","mage-g127","mage-g26","mage-g67","mage-g103","mage-g107","mage-g49","